-- Xóa dữ liệu cũ (nếu có) để tránh lỗi trùng lặp ID
TRUNCATE TABLE answer_image, question_image, answer, exam_question, question, exam RESTART IDENTITY CASCADE;

-- 1. Tạo 2 Exam

-- 2. Tạo 60 Question (Mỗi Exam 30 câu)

